// Some portions generated by Codex
package org.eclipse.rdf4j.query.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.junit.jupiter.api.Test;

class RemoteBNodeResponseScopeTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:p");

	@Test
	void recoveryRetainsEachOriginalColumnAndNestedComponentAuthority() {
		Object epoch = new Object();
		BNode parameter = alias(epoch);
		BNode first = alias(epoch);
		BNode second = alias(epoch);
		TripleTerm original = VF.createTripleTerm(first, PREDICATE,
				VF.createTripleTerm(second, PREDICATE, VF.createLiteral("old")));
		TripleTerm response = VF.createTripleTerm(parameter, PREDICATE,
				VF.createTripleTerm(parameter, PREDICATE, VF.createLiteral("new")));
		RemoteBNode.ResponseScope recovery = scope(epoch);
		recovery.seedOriginalBindings(bindings("parameter", parameter));
		BindingSet actual = recovery.recoverOriginalBindings(
				bindings("first", parameter, "second", parameter, "nested", response),
				bindings("first", first, "second", second, "nested", original));
		assertSame(first, actual.getValue("first"));
		assertSame(second, actual.getValue("second"));
		TripleTerm nested = (TripleTerm) actual.getValue("nested");
		assertSame(first, nested.getSubject());
		assertSame(second, ((TripleTerm) nested.getObject()).getSubject());
		assertEquals(VF.createLiteral("new"), ((TripleTerm) nested.getObject()).getObject());
	}

	@Test
	void recoveryDoesNotInterpretUntrustedPlainLabelsAsCanonicalIdentities() {
		Object epoch = new Object();
		BNode parameter = alias(epoch);
		BNode plain = VF.createBNode("canonical");
		TripleTerm raw = VF.createTripleTerm(plain, PREDICATE, plain);
		RemoteBNode.ResponseScope recovery = scope(epoch);
		recovery.seedOriginalBindings(bindings("parameter", parameter));
		BindingSet row = bindings("plain", plain, "nested", raw);
		BindingSet originals = bindings("plain", parameter, "nested",
				VF.createTripleTerm(parameter, PREDICATE, parameter));
		assertSame(row, recovery.recoverOriginalBindings(row));
		assertSame(row, recovery.recoverOriginalBindings(row, originals));
		assertSame(plain, recovery.recoverOriginalBindings(row, originals).getValue("plain"));
	}

	private static RemoteBNode.ResponseScope scope(Object epoch) {
		return RemoteBNode.newResponseScope(new BlankNodeAllocationScope(), VF, epoch, true);
	}

	private static BNode alias(Object epoch) {
		return (BNode) scope(epoch).map(VF.createBNode("canonical"));
	}

	private static BindingSet bindings(Object... entries) {
		MapBindingSet result = new MapBindingSet(entries.length / 2);
		for (int i = 0; i < entries.length; i += 2) {
			result.addBinding((String) entries[i], (Value) entries[i + 1]);
		}
		return result;
	}
}
